,"sector":"Technology (Financial Technology), Financial Services (Payment Technology & Processing)","hq":"Prague, Czech Republic","status":"current","invested_year":2015,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/wag-payment-solutions-as-eurowag/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Wealth Enhancement Group","slug":"wealth-enhancement-group","domain":"wealthenhancement.com","description":"Wealth Enhancement Group is one of the largest independent wealth management firms in the U.S.","sector":"Financial Services (Investment and Wealth Management)","hq":"Minneapolis, MN","status":"current","invested_year":2019,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/wealth-enhancement-group/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"WIND TELECOM S.p.A.","slug":"wind-telecom-s-p-a","domain":null,"description":"WIND TELECOM S.p.A. (formerly Weather Investments) is an international telecommunications company offering mobile, fixed, Internet and international communication services.","sector":"Technology (Infrastructure)","hq":"Rome, Italy","status":"realized","invested_year":2008,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/wind-telecom-spa/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"WorkWave","slug":"workwave","domain":"workwave.com","description":"WorkWave is a leading provider of cloud-based field service, fleet management and payment solutions for companies with a mobile workforce.","sector":"Technology (Financial Technology), Technology (Software), Financial Services (Payment Technology & Processing)","hq":"Holmdel, NJ","status":"current","invested_year":2020,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/workwave/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Yarra Capital Management","slug":"yarra-capital-management","domain":"yarracm.com","description":"Yarra Capital Management is a boutique and independent asset manager in Australia.","sector":"Financial Services (Investment and Wealth Management)","hq":"Melbourne, Australia","status":"current","invested_year":2017,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/yarra-capital-management/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"YeePay","slug":"yeepay","domain":"yeepay.com","description":"YeePay is a leading payments service provider in China.","sector":"Technology (Financial Technology), Financial Services (Payment Technology & Processing)","hq":"Beijing, China","status":"current","invested_year":2015,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/yeepay/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Youth and Family Centered Services, Inc.","slug":"youth-and-family-centered-services","domain":null,"description":"Youth and Family Centered Services was a provider of behavioral healthcare services to children and adolescents.","sector":"Healthcare (Healthcare Providers)","hq":"Austin, TX","status":"realized","invested_year":2004,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/youth-and-family-centered-services-inc/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Zadig & Voltaire","slug":"zadig-and-voltaire","domain":null,"description":"Zadig & Voltaire is a leading French brand in the accessible luxury ready-to-wear market, known for its Parisian-chic and rock and roll inspiration.","sector":"Consumer (Consumer Products)","hq":"Paris, France","status":"realized","invested_year":2012,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/zadig-voltaire/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Zifo","slug":"zifo","domain":"zifo.com","description":"Zifo is a leading provider of scientific informatics services.","sector":"Business Services (Outsourcing), Healthcare (Healthcare IT)","hq":"Chennai, India","status":"current","invested_year":2022,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/zifo-rnD-solutions/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"ZoomInfo","slug":"zoominfo","domain":"zoominfo.com","description":"ZoomInfo (NASDAQ: ZI) is a Go-To-Market Intelligence Solution for more than 30,000 companies worldwide.","sector":"Business Services (Information Services), Technology (Software)","hq":"Vancouver, WA","status":"realized","invested_year":2014,"exit_year":null,"fund_name":null,"source_url":"https://www.ta.com/portfolio/investments/zoominfo/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null}],"deals":[]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'TA Associates'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'TA Associates'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'ta.com Nuxt static payloads: /_nuxt/static/1790782985/portfolio/payload.js (full 322-company list with status/sector/region) plus /portfolio/investments/payload.js and each /portfolio/investments/<slug>/payload.js (website, location, investment year, headline); cross-checked against all 418 /news/ payloads (every investment announcement links to a listed company)', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'TA Associates', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
